from __future__ import annotations

import math
from copy import deepcopy
from datetime import datetime
from typing import Any, Iterable

import numpy as np

from .registry import (
    CORE_METRIC_IDS,
    DIMENSION_RULES,
    LOW_DIRECTION_METRICS,
    PROFILE_VERSION,
    public_registry,
)


QUANTILES = {
    "p005": 0.005, "p10": 0.10, "p25": 0.25, "p50": 0.50,
    "p75": 0.75, "p90": 0.90, "p95": 0.95, "p995": 0.995,
}


def _transform_name(metric: str) -> str:
    lower = metric.lower()
    if any(token in lower for token in ("count", "density", "area_px", "length_px", "width_px", "volume")):
        return "log1p"
    return "identity"


def _transform(value: float, name: str) -> float:
    return math.log1p(max(0.0, value)) if name == "log1p" else float(value)


def _finite_number(value: Any) -> float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    number = float(value)
    return number if math.isfinite(number) else None


def _merge_histograms(histograms: Iterable[dict[str, Any]]) -> dict[str, Any] | None:
    merged: np.ndarray | None = None
    bin_width = maximum = None
    for histogram in histograms:
        counts = np.asarray(histogram.get("counts") or [], dtype=np.int64)
        if counts.size == 0:
            continue
        current_width = float(histogram.get("bin_width", 0.0))
        current_maximum = float(histogram.get("maximum", 0.0))
        if merged is None:
            merged = np.zeros_like(counts)
            bin_width, maximum = current_width, current_maximum
        if counts.shape != merged.shape or current_width != bin_width or current_maximum != maximum:
            raise ValueError("V0.2 calibration histogram schema mismatch")
        merged += counts
    if merged is None:
        return None
    return {
        "bin_width": bin_width,
        "maximum": maximum,
        "sample_count": int(merged.sum()),
        "counts": merged.tolist(),
    }


def _histogram_quantile(histogram: dict[str, Any] | None, quantile: float) -> float:
    if not histogram:
        return 0.0
    counts = np.asarray(histogram.get("counts") or [], dtype=np.int64)
    total = int(counts.sum())
    if total <= 0:
        return 0.0
    index = int(np.searchsorted(np.cumsum(counts), max(1.0, quantile * total), side="left"))
    return float(index * float(histogram["bin_width"]))


def _histogram_ratio(
    histogram: dict[str, Any] | None, threshold: float, *, above: bool
) -> float:
    if not histogram:
        return 0.0
    counts = np.asarray(histogram.get("counts") or [], dtype=np.int64)
    total = int(counts.sum())
    if total <= 0:
        return 0.0
    values = np.arange(counts.size, dtype=np.float64) * float(histogram["bin_width"])
    selected = values > threshold if above else values <= threshold
    return float(counts[selected].sum() / total)


def derive_calibration_thresholds_v02(observations: Iterable[dict[str, Any]]) -> dict[str, Any]:
    scopes: dict[str, dict[str, list[dict[str, Any]]]] = {}
    for observation in observations:
        gate = observation.get("gate") or {}
        if gate.get("status") != "PASS" or not gate.get("reference_eligible"):
            continue
        evidence = observation.get("evidence") or observation
        support = evidence.get("calibration_support") or {}
        for scope_name, scope_support in [("__overall__", support.get("overall") or {})]:
            for metric, histogram in scope_support.items():
                scopes.setdefault(scope_name, {}).setdefault(metric, []).append(histogram)
        for region, region_support in (support.get("regions") or {}).items():
            for metric, histogram in region_support.items():
                scopes.setdefault(region, {}).setdefault(metric, []).append(histogram)

    thresholds: dict[str, Any] = {"overall": {}, "regions": {}}
    for scope, metric_histograms in scopes.items():
        merged = {
            metric: _merge_histograms(histograms)
            for metric, histograms in metric_histograms.items()
        }
        values = {
            "large_pore_area_px_p75": _histogram_quantile(merged.get("pore_area_px"), 0.75),
            "fine_line_length_px_p25": _histogram_quantile(merged.get("fine_line_length_px"), 0.25),
            "fine_line_width_px_p25": _histogram_quantile(merged.get("fine_line_width_px"), 0.25),
        }
        if scope == "__overall__":
            thresholds["overall"] = values
        else:
            thresholds["regions"][scope] = values
    return thresholds


def apply_calibration_thresholds_v02(
    evidence: dict[str, Any], thresholds: dict[str, Any]
) -> dict[str, Any]:
    """Populate distribution-derived ratios without changing raw evidence."""
    support = evidence.get("calibration_support") or {}

    def apply(groups: dict[str, Any], local_support: dict[str, Any], values: dict[str, Any]) -> None:
        if not groups or not local_support or not values:
            return
        groups["visible_pores"]["large_pores"]["large_pore_ratio"] = round(
            _histogram_ratio(
                local_support.get("pore_area_px"),
                float(values.get("large_pore_area_px_p75", 0.0)),
                above=True,
            ), 8
        )
        scale = groups["dry_fine_lines"]["scale"]
        scale["short_line_ratio"] = round(
            _histogram_ratio(
                local_support.get("fine_line_length_px"),
                float(values.get("fine_line_length_px_p25", 0.0)),
                above=False,
            ), 8
        )
        scale["narrow_line_ratio"] = round(
            _histogram_ratio(
                local_support.get("fine_line_width_px"),
                float(values.get("fine_line_width_px_p25", 0.0)),
                above=False,
            ), 8
        )

    apply(evidence.get("dimensions") or {}, support.get("overall") or {}, thresholds.get("overall") or {})
    visible_regions = set()
    for regions in (evidence.get("region_metrics") or {}).values():
        visible_regions.update(regions)
    for region in visible_regions:
        groups = {
            dimension: (regions.get(region) or {})
            for dimension, regions in (evidence.get("region_metrics") or {}).items()
        }
        if not groups.get("visible_pores") or not groups.get("dry_fine_lines"):
            continue
        apply(
            groups,
            ((support.get("regions") or {}).get(region) or {}),
            ((thresholds.get("regions") or {}).get(region) or thresholds.get("overall") or {}),
        )
    return evidence


def _iter_metric_paths(evidence: dict[str, Any]) -> Iterable[tuple[str, str, str, str | None, float]]:
    for dimension, groups in (evidence.get("dimensions") or {}).items():
        registered_groups = CORE_METRIC_IDS.get(dimension, {})
        for group, metrics in (groups or {}).items():
            registered_metrics = set(registered_groups.get(group, ()))
            for metric, raw in (metrics or {}).items():
                if metric not in registered_metrics:
                    continue
                value = _finite_number(raw)
                if value is not None:
                    yield dimension, group, metric, None, value
    for dimension, regions in (evidence.get("region_metrics") or {}).items():
        registered_groups = CORE_METRIC_IDS.get(dimension, {})
        for region, groups in (regions or {}).items():
            for group, metrics in (groups or {}).items():
                registered_metrics = set(registered_groups.get(group, ()))
                for metric, raw in (metrics or {}).items():
                    if metric not in registered_metrics:
                        continue
                    value = _finite_number(raw)
                    if value is not None:
                        yield dimension, group, metric, region, value


def build_profile_v02(observations: Iterable[dict[str, Any]]) -> dict[str, Any]:
    observations = list(observations)
    derived_thresholds = derive_calibration_thresholds_v02(observations)
    buckets: dict[str, list[float]] = {}
    raw_counts: dict[str, int] = {}
    sample_count = 0
    for observation in observations:
        gate = observation.get("gate") or {}
        if gate.get("status") != "PASS" or not gate.get("reference_eligible"):
            continue
        evidence = observation.get("evidence") or observation
        apply_calibration_thresholds_v02(evidence, derived_thresholds)
        sample_count += 1
        for dimension, group, metric, region, raw in _iter_metric_paths(evidence):
            transform = _transform_name(metric)
            location = region or "__overall__"
            key = f"{dimension}|{location}|{group}|{metric}|{transform}"
            buckets.setdefault(key, []).append(_transform(raw, transform))
            raw_counts[key] = raw_counts.get(key, 0) + 1
    metrics: dict[str, Any] = {}
    for key in sorted(buckets):
        values = np.asarray(buckets[key], dtype=np.float64)
        dimension, location, group, metric, transform = key.split("|", 4)
        entry = {
            "dimension": dimension,
            "region": None if location == "__overall__" else location,
            "group": group,
            "metric": metric,
            "transform": transform,
            "sample_count": int(values.size),
            "usable": bool(values.size >= 30 and np.ptp(values) > 1e-12),
            **{name: round(float(np.quantile(values, q)), 10) for name, q in QUANTILES.items()},
        }
        metrics[key] = entry
    return {
        "profile_version": PROFILE_VERSION,
        "created_at": datetime.now().astimezone().isoformat(timespec="seconds"),
        "calibration_status": "candidate/uncalibrated",
        "algorithm_evidence_version": "algorithm_evidence_v0.2-test",
        "quality_gate_version": "input_quality_gate_v0.2",
        "reference_sample_count": sample_count,
        "quantiles": list(QUANTILES),
        "metrics": metrics,
        "registry": public_registry(),
        "derived_thresholds": derived_thresholds,
    }


def _metric_key(dimension: str, region: str | None, group: str, metric: str) -> str:
    transform = _transform_name(metric)
    return f"{dimension}|{region or '__overall__'}|{group}|{metric}|{transform}"


def _percentile_score(raw: float, profile: dict[str, Any], *, low_direction: bool) -> float | None:
    if not profile or not profile.get("usable"):
        return None
    value = _transform(raw, str(profile.get("transform", "identity")))
    nodes = [(float(profile[name]), q * 100.0) for name, q in QUANTILES.items()]
    nodes.sort()
    if value <= nodes[0][0]:
        percentile = 0.0
    elif value >= nodes[-1][0]:
        percentile = 100.0
    else:
        percentile = 0.0
        for (x0, p0), (x1, p1) in zip(nodes, nodes[1:]):
            if x0 <= value <= x1:
                percentile = p1 if x1 <= x0 else p0 + (value - x0) * (p1 - p0) / (x1 - x0)
                break
    score = 100.0 - percentile if low_direction else percentile
    # Explicit absence is no burden for direct target metrics.  Shape,
    # continuity and uniformity metrics are intentionally excluded.
    metric = str(profile.get("metric", ""))
    absence_tokens = ("count", "density", "area_ratio", "area_px", "length", "width", "volume", "gloss")
    if raw <= 0.0 and any(token in metric for token in absence_tokens):
        score = 0.0
    return float(np.clip(score, 0.0, 100.0))


def _score_groups(
    dimension: str,
    groups: dict[str, Any],
    profile: dict[str, Any],
    *,
    region: str | None,
) -> tuple[float | None, dict[str, Any]]:
    rule = DIMENSION_RULES[dimension]
    weighted = weight_sum = 0.0
    trace: dict[str, Any] = {}
    for group, weight in rule["groups"].items():
        metric_scores: list[float] = []
        metric_trace: list[dict[str, Any]] = []
        registered_metrics = CORE_METRIC_IDS[dimension].get(group, ())
        for metric in registered_metrics:
            raw = (groups.get(group) or {}).get(metric)
            value = _finite_number(raw)
            if value is None:
                continue
            key = _metric_key(dimension, region, group, metric)
            metric_profile = (profile.get("metrics") or {}).get(key)
            low = (dimension, group, metric) in LOW_DIRECTION_METRICS
            score = _percentile_score(value, metric_profile, low_direction=low)
            if score is None:
                continue
            metric_scores.append(score)
            metric_trace.append({
                "metric_id": metric, "raw_value": value,
                "transform": metric_profile.get("transform"),
                "burden_score": round(score, 6), "profile_key": key,
            })
        if not metric_scores:
            continue
        group_score = float(np.mean(metric_scores))
        trace[group] = {
            "weight": weight, "score": round(group_score, 6),
            "metrics": metric_trace,
        }
        weighted += group_score * float(weight)
        weight_sum += float(weight)
    return ((weighted / weight_sum) if weight_sum else None), trace


def _grade(score: float | None) -> str | None:
    if score is None:
        return None
    if score <= 20:
        return "未见明显"
    if score <= 40:
        return "轻度"
    if score <= 60:
        return "中度"
    if score <= 80:
        return "较明显"
    return "显著"


def score_evidence_v02(evidence: dict[str, Any], profile: dict[str, Any]) -> dict[str, Any]:
    # Work on a copy so scoring never mutates the archived raw evidence.
    evidence = apply_calibration_thresholds_v02(
        deepcopy(evidence), profile.get("derived_thresholds") or {}
    )
    results: dict[str, Any] = {}
    for dimension, rule in DIMENSION_RULES.items():
        region_weights = rule.get("regions") or {}
        region_scores: dict[str, Any] = {}
        weighted = weight_sum = 0.0
        for region, weight in region_weights.items():
            groups = (((evidence.get("region_metrics") or {}).get(dimension) or {}).get(region) or {})
            score, trace = _score_groups(dimension, groups, profile, region=region)
            if score is None:
                continue
            region_scores[region] = {"weight": weight, "score": round(score, 6), "groups": trace}
            weighted += score * float(weight)
            weight_sum += float(weight)
        if weight_sum:
            dimension_score = weighted / weight_sum
            overall_trace = None
        else:
            groups = ((evidence.get("dimensions") or {}).get(dimension) or {})
            dimension_score, overall_trace = _score_groups(dimension, groups, profile, region=None)
        results[dimension] = {
            "name": rule["name"],
            "score": round(dimension_score, 6) if dimension_score is not None else None,
            "grade": _grade(dimension_score),
            "regions": region_scores,
            "overall_groups": overall_trace,
        }
    valid_scores = [item["score"] for item in results.values() if isinstance(item.get("score"), (int, float))]
    overall = float(np.mean(valid_scores)) if len(valid_scores) == len(DIMENSION_RULES) else None
    return {
        "scoring_profile_version": profile.get("profile_version"),
        "calibration_status": "candidate/uncalibrated",
        "score_direction": "higher_is_more_visible_burden",
        "dimensions": results,
        "overall_score": round(overall, 6) if overall is not None else None,
        "overall_grade": _grade(overall),
        "smoothness_display_score": round(100.0 - results["surface_smoothness_decline"]["score"], 6)
        if isinstance(results["surface_smoothness_decline"].get("score"), (int, float)) else None,
    }
from __future__ import annotations

from typing import Any


PROFILE_VERSION = "aisia_scoring_v0.2_test_202608"
REGISTRY_VERSION = "doctor_scoring_v0.2_test_202608"


