def _metric_unit(metric: str) -> str:
    if "per_100k" in metric or metric.endswith("_density") or metric == "pore_density":
        return "per_100k_valid_skin_pixels"
    if metric.endswith("_px") or "length_px" in metric or "width_px" in metric:
        return "standardized_1024_pixels"
    if "ratio" in metric or metric in {"continuity", "uniformity", "direction_entropy"}:
        return "ratio_0_to_1"
    if "intensity" in metric or "contrast" in metric or "redness" in metric or "gloss" in metric:
        return "engineering_normalized_value"
    return "engineering_value"


def _metric_formula(metric: str) -> str:
    if "per_100k" in metric or metric.endswith("_density") or metric == "pore_density":
        return "target_count_or_length * 100000 / valid_skin_area_px"
    if metric.endswith("_ratio") or metric in {"continuity", "uniformity"}:
        return "target_measure / corresponding_valid_measure"
    if metric.startswith("p50_"):
        return "median(valid_target_values)"
    if metric.startswith("p90_"):
        return "percentile(valid_target_values, 90)"
    if metric.startswith("mean_"):
        return "mean(valid_target_values)"
    return "dimension_specific_engineering_measure"


def metric_definitions() -> list[dict[str, Any]]:
    definitions: list[dict[str, Any]] = []
    for dimension, groups in CORE_METRIC_IDS.items():
        for group, metrics in groups.items():
            for metric in metrics:
                definitions.append({
                    "canonical_id": f"{dimension}.{group}.{metric}",
                    "dimension": dimension,
                    "dimension_name": DIMENSION_RULES[dimension]["name"],
                    "group": group,
                    "group_weight": DIMENSION_RULES[dimension]["groups"][group],
                    "metric": metric,
                    "unit": _metric_unit(metric),
                    "formula": _metric_formula(metric),
                    "score_direction": "lower_is_more_burden"
                    if (dimension, group, metric) in LOW_DIRECTION_METRICS
                    else "higher_is_more_burden",
                    "source_spec": "medical_requirements_v2_20260728",
                })
    return definitions


LOW_DIRECTION_METRICS = {
    ("diffuse_redness", "boundary_uniformity", "boundary_gradient"),
}


def public_registry() -> dict[str, Any]:
    return {
        "registry_version": REGISTRY_VERSION,
        "doctor_spec_version": "medical_requirements_v2_20260728",
        "algorithm_evidence_version": "algorithm_evidence_v0.2-test",
        "quality_gate_version": "input_quality_gate_v0.2",
        "calibration_status": "candidate/uncalibrated",
        "score_direction": "higher_is_more_visible_burden",
        "overall_rule": "eleven_dimensions_equal_weight_using_smoothness_decline",
        "grade_thresholds": [
            {"min": 0, "max": 20, "label": "未见明显"},
            {"min": 20, "max": 40, "label": "轻度"},
            {"min": 40, "max": 60, "label": "中度"},
            {"min": 60, "max": 80, "label": "较明显"},
            {"min": 80, "max": 100, "label": "显著"},
        ],
        "dimensions": DIMENSION_RULES,
        "core_metric_ids": CORE_METRIC_IDS,
        "metric_definitions": metric_definitions(),
    }

