QUANTILES = (("P0.5", .005), ("P10", .10), ("P25", .25), ("P50", .50), ("P75", .75), ("P90", .90), ("P95", .95), ("P99.5", .995))


def _quantile(values: list[float], q: float) -> float | None:
    if not values:
        return None
    position = (len(values) - 1) * q
    lower, upper = math.floor(position), math.ceil(position)
    if lower == upper:
        return values[lower]
    return values[lower] + (values[upper] - values[lower]) * (position - lower)


def _write_definitions(path: Path) -> None:
    with path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(("维度ID", "维度名称", "医生依据", "二级维度ID", "二级维度名称", "二级权重", "指标ID", "canonical来源", "指标权重", "变换", "方向", "单位", "零膨胀", "最小实例数"))
        for dimension in REGISTRY:
            for group in dimension.groups:
                for metric in group.metrics:
                    writer.writerow((dimension.id, dimension.name, dimension.doctor_source, group.id, group.name, group.weight, metric.id, metric.source, metric.weight, metric.transform, metric.direction, metric.unit, metric.zero_inflated, metric.minimum_instances))


def _write_distributions(profile: dict, path: Path) -> None:
    with path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(("指标ID", "有效样本数", *(name for name, _ in QUANTILES)))
        for metric_id, values in profile["references"].items():
            writer.writerow((metric_id, len(values), *(_quantile(values, q) for _, q in QUANTILES)))


def _quality_summary(database: Path) -> dict:
    connection = sqlite3.connect(database)
    try:
        by_status = dict(connection.execute("SELECT quality_status,COUNT(*) FROM samples GROUP BY quality_status"))
        reasons: dict[str, int] = {}
        for raw, count in connection.execute("SELECT reason_codes_json,COUNT(*) FROM samples GROUP BY reason_codes_json"):
            for reason in json.loads(raw):
                reasons[reason] = reasons.get(reason, 0) + int(count)
        total = int(connection.execute("SELECT COUNT(*) FROM samples").fetchone()[0])
    finally:
        connection.close()
    return {"total_samples": total, "quality_status_counts": by_status, "exclusion_reason_counts": dict(sorted(reasons.items()))}


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def main() -> int:
    parser = argparse.ArgumentParser(description="AISIA评分V0.1.1完整性常模构建")
    parser.add_argument("--jsonl", type=Path, action="append", required=True, help="可重复指定；只顺序读取新增行")
    parser.add_argument("--workspace", type=Path, required=True, help="建议放NVMe；低于10GiB将保留供增量更新")
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--workspace-limit-gib", type=float, default=10.0)
    parser.add_argument("--minimum-reference-samples", type=int, default=1000)
    args = parser.parse_args()
    args.workspace.mkdir(parents=True, exist_ok=True)
    database = args.workspace / "population_v011.sqlite3"
    counters = ingest_jsonl(args.jsonl, database, workspace_limit_bytes=int(args.workspace_limit_gib * 1024 ** 3))
    profile = build_exact_profile(database)
    args.output.mkdir(parents=True, exist_ok=True)
    target = args.output / "aisia_scoring_v0.1.1_integrity_20260806.json"
    minimum_count = min(profile["effective_metric_counts"].values(), default=0)
    profile["minimum_required_reference_samples"] = args.minimum_reference_samples
    profile["profile_ready"] = minimum_count >= args.minimum_reference_samples
    profile["minimum_effective_metric_count"] = minimum_count
    target.write_text(json.dumps(profile, ensure_ascii=False, indent=2, allow_nan=False), encoding="utf-8")
    definitions = args.output / "V0.1.1_四项正式评分指标定义.csv"
    distributions = args.output / "V0.1.1_四项参考分布.csv"
    _write_definitions(definitions)
    _write_distributions(profile, distributions)
    quality = _quality_summary(database)
    summary = {
        "scoring_profile_version": profile["scoring_profile_version"],
        "status": profile["status"], "profile_ready": profile["profile_ready"],
        "import": counters, **quality,
        "minimum_effective_metric_count": minimum_count,
        "minimum_required_reference_samples": args.minimum_reference_samples,
        "workspace_bytes": sum(path.stat().st_size for path in args.workspace.iterdir() if path.is_file()),
        "workspace_limit_gib": args.workspace_limit_gib,
        "files": {"profile": target.name, "definitions": definitions.name, "distributions": distributions.name},
        "sha256": {"profile": _sha256(target), "definitions": _sha256(definitions), "distributions": _sha256(distributions)},
    }
    summary_path = args.output / "V0.1.1构建摘要.json"
    summary_path.write_text(json.dumps(summary, ensure_ascii=False, indent=2, allow_nan=False), encoding="utf-8")
    print(json.dumps({"database": str(database), "profile": str(target), "summary": str(summary_path), **summary}, ensure_ascii=False, indent=2))
