from __future__ import annotations

import argparse
import json
import os
import sqlite3
from pathlib import Path
from typing import Any, Iterator

from src.preprocess.image_preprocessor import ImagePreprocessor
from src.nine_analysis.metrics import extract_item
from src.scoring_calibration.v011.quality import evaluate_image_path


def _directories(path: Path, prefix: str | None = None) -> Iterator[Path]:
    with os.scandir(path) as entries:
        names = sorted(
            entry.name for entry in entries
            if entry.is_dir(follow_symlinks=False) and (prefix is None or entry.name.startswith(prefix))
        )
    for name in names:
        yield path / name


def _input_image(sample: Path) -> Path | None:
    for name in os.listdir(sample):
        if name.startswith("00_输入图片") and (sample / name).is_file():
            return sample / name
    return None


def _features(sample: Path) -> dict[str, Any] | None:
    path = sample / "九项核心量化指标.json"
    if not path.is_file():
        return None
    try:
        document = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return None
    items = document.get("九项") or {}
    features = {
        key: value.get("评分输入") or {}
        for key, value in items.items()
        if isinstance(value, dict)
    }
    # 历史结果生成时紫区评分输入可能为空，但正式精简JSON仍保留了
    # uv_spots_total等稳定计数。只从该正式JSON重建评分输入，不读取
    # 已删除的中间医学JSON，也不修改原结果。
    for key in ("uv_spots", "porphyrin"):
        if features.get(key):
            continue
        item = items.get(key) or {}
        relative_json = item.get("量化JSON")
        metric_path = sample / str(relative_json) if relative_json else None
        if metric_path and metric_path.is_file():
            try:
                raw = json.loads(metric_path.read_text(encoding="utf-8-sig"))
                _, rebuilt = extract_item(key, raw)
                features[key] = rebuilt
            except (OSError, UnicodeError, json.JSONDecodeError):
                pass
    return features if len(features) == 9 else None


def main() -> int:
    parser = argparse.ArgumentParser(description="从已有review结果顺序提取V0.1.1常模输入，不修改原始结果")
    parser.add_argument("--review-root", type=Path, required=True)
    parser.add_argument("--workspace", type=Path, required=True)
    parser.add_argument("--workspace-limit-gib", type=float, default=10.0)
    parser.add_argument("--limit", type=int)
    args = parser.parse_args()
    root = args.review_root.resolve()
    workspace = args.workspace.resolve()
    workspace.mkdir(parents=True, exist_ok=True)
    database = workspace / "review_scan_v011.sqlite3"
    output = workspace / "review_observations_v011.jsonl"
    connection = sqlite3.connect(database)
    connection.execute("PRAGMA journal_mode=WAL")
    connection.execute("PRAGMA synchronous=NORMAL")
    connection.execute("CREATE TABLE IF NOT EXISTS completed (relative_path TEXT PRIMARY KEY, status TEXT NOT NULL)")
    preprocessor = ImagePreprocessor()
    counters = {"seen": 0, "written": 0, "skipped_completed": 0, "missing_input": 0, "missing_features": 0}
    mode = "a" if output.exists() else "w"
    try:
        with output.open(mode, encoding="utf-8") as target:
            for batch in _directories(root, "batch_"):
                for sample in _directories(batch):
                    relative = sample.relative_to(root).as_posix()
                    if connection.execute("SELECT 1 FROM completed WHERE relative_path=?", (relative,)).fetchone():
                        counters["skipped_completed"] += 1
                        continue
                    counters["seen"] += 1
                    image = _input_image(sample)
                    features = _features(sample)
                    if image is None:
                        counters["missing_input"] += 1
                        status = "missing_input"
                    elif features is None:
                        counters["missing_features"] += 1
                        status = "missing_features"
                    else:
                        gate = evaluate_image_path(image, preprocessor)
                        observation = {
                            "signature": {"relative_path": relative, "size": image.stat().st_size, "mtime_ns": image.stat().st_mtime_ns},
                            "status": "success",
                            "input_quality_gate": gate,
                            "quality": {"status": gate["status"], "flags": gate["reason_codes"]},
                            "content_sha256": gate["source_sha256"],
                            "perceptual_hash": gate["perceptual_hash"],
                            "algorithm_version": "nine_analysis_dev_97feba3",
                            "metrics_schema_version": "scoring_features_v1",
                            "scoring_features": features,
                        }
                        target.write(json.dumps(observation, ensure_ascii=False, allow_nan=False, separators=(",", ":")) + "\n")
                        counters["written"] += 1
                        status = gate["status"]
                    connection.execute("INSERT INTO completed VALUES (?,?)", (relative, status))
                    if counters["seen"] % 100 == 0:
                        target.flush()
                        connection.commit()
                        size = sum(path.stat().st_size for path in workspace.iterdir() if path.is_file())
                        if size > args.workspace_limit_gib * 1024 ** 3:
                            raise RuntimeError("评分扫描工作区超过限制，已保留断点并停止")
                    if args.limit is not None and counters["seen"] >= args.limit:
                        break
                if args.limit is not None and counters["seen"] >= args.limit:
                    break
            target.flush()
            connection.commit()
    finally:
        connection.close()
    print(json.dumps({**counters, "observation_jsonl": str(output), "scan_database": str(database)}, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
