from datetime import datetime
from pathlib import Path
from typing import Any

from .adapters import adapt_acne, adapt_dermavision, adapt_wrinkle
from .models import ModuleResult, sanitize_json


MODULE_ORDER = [
    "pores",
    "oil",
    "pigmentation",
    "redness",
    "vascular",
    "acne",
    "dry_lines",
    "wrinkle",
    "grooves",
