        "display_only_dimensions": list(DISPLAY_ONLY_DIMENSIONS),
        "overall_score": None,
        "dimensions": [asdict(item) for item in REGISTRY],
    }
    encoded = json.dumps(body, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
    body["registry_sha256"] = hashlib.sha256(encoded).hexdigest()
    return body
from __future__ import annotations

import bisect
import hashlib
import json
import math
from typing import Any

from .quality import evaluate_quality
from .registry import DISPLAY_ONLY_DIMENSIONS, REGISTRY, MetricSpec, registry_document


def transform_value(value: float, transform: str) -> float:
    if not math.isfinite(value):
        raise ValueError("指标值不是有限数")
    if transform == "identity":
        return value
    if transform == "log1p":
        if value < 0:
            raise ValueError("log1p指标不得为负数")
        return math.log1p(value)
    raise ValueError(f"未知变换: {transform}")


def empirical_percentile(value: float, reference: list[float], direction: str = "high") -> tuple[float, dict[str, Any]]:
    """完整经验CDF；并列值使用中位秩，不截断到0.5/99.5。"""
    if not reference:
        raise ValueError("参考分布为空")
    values = sorted(float(item) for item in reference if math.isfinite(float(item)))
    if not values:
        raise ValueError("参考分布没有有限值")
    left = bisect.bisect_left(values, value)
    right = bisect.bisect_right(values, value)
    midrank = (left + right) / 2.0
    percentile = 100.0 * midrank / len(values)
    if direction == "low":
        percentile = 100.0 - percentile
    return percentile, {
        "reference_count": len(values),
        "cdf_left_count": left,
        "cdf_right_count": right,
        "tie_count": right - left,
        "midrank": midrank,
    }


def _metric_score(metric: MetricSpec, raw_value: float, references: dict[str, list[float]]) -> tuple[float, dict[str, Any]]:
    transformed = transform_value(float(raw_value), metric.transform)
    reference = list(references.get(metric.id) or [])
    if metric.zero_is_no_burden and float(raw_value) == 0:
        return 0.0, {
            "raw_value": float(raw_value), "transformed_value": transformed,
            "score": 0.0, "mapping": "zero_burden", "reference_count": len(reference),
        }
    if metric.zero_inflated:
        reference = [item for item in reference if item > 0]
        mapping = "positive_only_empirical_cdf"
    else:
        mapping = "full_empirical_cdf"
    score, detail = empirical_percentile(transformed, reference, metric.direction)
    return score, {
        "raw_value": float(raw_value), "transformed_value": transformed,
        "score": score, "mapping": mapping, "direction": metric.direction,
        "transform": metric.transform, "unit": metric.unit, **detail,
    }


def _get_path(features: dict[str, Any], path: str) -> Any:
    node: Any = features
    for part in path.split("."):
        if not isinstance(node, dict) or part not in node:
            return None
        node = node[part]
    return node


def score_observation(
    observation: dict[str, Any],
    references: dict[str, list[float]],
    *,
    include_legacy_shadow: bool = False,
    normalization_profile_sha256: str | None = None,
    scoring_profile_version: str | None = None,
) -> dict[str, Any]:
    config = registry_document()
    gate = evaluate_quality(observation)
    features = observation.get("features") or observation.get("scoring_features") or {}
    dimensions: list[dict[str, Any]] = []
    formal_allowed = gate["status"] == "PASS"

    for dimension in REGISTRY:
        groups: list[dict[str, Any]] = []
        missing_groups: list[str] = []
        for group in dimension.groups:
            metric_rows: list[dict[str, Any]] = []
            missing_metrics: list[str] = []
            for metric in group.metrics:
                raw = _get_path(features, metric.source)
                count = _get_path(features, metric.source.split(".")[0] + ".instance_count")
                if metric.minimum_instances and count is not None and int(count) < metric.minimum_instances:
                    missing_metrics.append(metric.id)
                    continue
                if raw is None or isinstance(raw, bool) or not isinstance(raw, (int, float)):
                    missing_metrics.append(metric.id)
                    continue
                try:
                    score, detail = _metric_score(metric, float(raw), references)
                except ValueError:
                    missing_metrics.append(metric.id)
                    continue
                metric_rows.append({
                    "metric_id": metric.id, "canonical_source": metric.source,
                    "metric_weight": metric.weight, **detail,
                })
            if missing_metrics:
                missing_groups.append(group.id)
                groups.append({
                    "group_id": group.id, "group_name": group.name, "group_weight": group.weight,
                    "status": "insufficient_evidence", "missing_metrics": missing_metrics,
                    "metrics": metric_rows, "score": None,
                })
                continue
            group_score = sum(row["score"] * row["metric_weight"] for row in metric_rows)
            groups.append({
                "group_id": group.id, "group_name": group.name, "group_weight": group.weight,
                "status": "scored", "missing_metrics": [], "metrics": metric_rows,
                "score": group_score,
            })
        if not formal_allowed:
            status = "shadow_only" if gate["status"] == "REVIEW" else "not_scored"
            dimension_score = None
        elif missing_groups:
            status = "insufficient_evidence"
            dimension_score = None
        else:
            status = "formal"
            dimension_score = sum(row["score"] * row["group_weight"] for row in groups)
        dimensions.append({
            "dimension_id": dimension.id, "dimension_name": dimension.name,
            "status": status, "score": dimension_score, "groups": groups,
            "missing_required_groups": missing_groups,
        })

    result: dict[str, Any] = {
        "scoring_profile_version": scoring_profile_version or config["scoring_profile_version"],
        "calibration_status": config["status"],
        "score_direction": config["score_direction"],
        "quality_gate": gate,
        "formal_dimension_scores": dimensions,
        "display_only_dimensions": list(DISPLAY_ONLY_DIMENSIONS),
        "overall_score": None,
        "overall_grade": None,
        "registry_sha256": config["registry_sha256"],
        "normalization_profile_sha256": normalization_profile_sha256,
    }
    if include_legacy_shadow:
        result["legacy_shadow_score"] = observation.get("legacy_score")
    stable = json.dumps(result, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    result["trace_sha256"] = hashlib.sha256(stable.encode()).hexdigest()
    return result
from __future__ import annotations

import hashlib
from pathlib import Path
from typing import Any, Literal

import cv2
import numpy as np

from src.preprocess.image_preprocessor import ImagePreprocessor


GateStatus = Literal["PASS", "REVIEW", "REJECT"]

REJECT_CODES = {
    "decode_failed", "no_face", "multiple_faces", "multi_face", "collage",
    "multi_panel", "heatmap", "pseudo_color", "result_image", "severe_mosaic",
}
REVIEW_CODES = {
    "strong_filter", "beauty_filter", "skin_smoothing", "unstable_lighting",
    "partial_occlusion", "partial_face", "low_contrast", "blur",
}


def evaluate_quality(observation: dict[str, Any]) -> dict[str, Any]:
    gate = observation.get("input_quality_gate") or observation.get("quality_gate")
    quality = observation.get("quality") or {}
    if not isinstance(gate, dict):
        # 九项算法自身的quality_status只能描述算法输入质量，不能替代
        # 评分常模要求的原图派生图/拼接图门禁。
        return {
            "gate_version": "input_quality_gate_v0.1.1_integrity",
            "status": "REVIEW",
            "reference_eligible": False,
            "formal_score_eligible": False,
            "reason_codes": ["missing_input_quality_gate"],
            "algorithm_quality": quality,
        }
    reasons = set(gate.get("reason_codes") or [])
    declared = str(gate.get("status") or "").upper()
    if reasons & REJECT_CODES or declared == "REJECT":
        status: GateStatus = "REJECT"
    elif reasons & REVIEW_CODES or declared == "REVIEW":
        status = "REVIEW"
    elif declared == "PASS" and observation.get("status", "success") in {"success", "partial_success"}:
        status = "PASS"
    else:
        status = "REVIEW"
        reasons.add("missing_quality_gate")
    return {
        "gate_version": "input_quality_gate_v0.1.1_integrity",
        "status": status,
        "reference_eligible": status == "PASS",
        "formal_score_eligible": status == "PASS",
        "reason_codes": sorted(reasons),
    }


def region_is_valid(region: dict[str, Any]) -> tuple[bool, list[str]]:
    reasons: list[str] = []
    valid_pixels = float(region.get("valid_pixels") or region.get("valid_area_px") or 0)
    mask_pixels = float(region.get("anatomical_mask_pixels") or region.get("mask_area_px") or 0)
    if valid_pixels < 2000:
        reasons.append("valid_pixels_lt_2000")
    if mask_pixels <= 0 or valid_pixels / mask_pixels < .5:
        reasons.append("coverage_lt_50_percent")
    return not reasons, reasons


def instance_metric_is_valid(metric_kind: str, instance_count: int) -> tuple[bool, str | None]:
    if metric_kind in {"p50", "p90", "morphology"} and instance_count < 5:
        return False, "instance_count_lt_5"
    if metric_kind in {"p90", "ratio", "morphology"} and instance_count < 10:
        return False, "instance_count_lt_10"
    if 10 <= instance_count < 20:
        return True, "low_stability_n_lt_20"
    return True, None


def _resize(image: np.ndarray, limit: int = 512) -> np.ndarray:
    height, width = image.shape[:2]
    scale = min(1.0, limit / max(height, width))
    if scale >= 1:
        return image.copy()
    return cv2.resize(image, (round(width * scale), round(height * scale)), interpolation=cv2.INTER_AREA)


def _image_derived_features(image: np.ndarray) -> dict[str, Any]:
    small = _resize(image)
    lab = cv2.cvtColor(small, cv2.COLOR_BGR2LAB).astype(np.float32)
    vertical = np.linalg.norm(lab[:, 1:] - lab[:, :-1], axis=2)
    horizontal = np.linalg.norm(lab[1:] - lab[:-1], axis=2)
    vp = np.percentile(vertical, 65, axis=0)
    hp = np.percentile(horizontal, 65, axis=1)
    vlo, vhi = int(len(vp) * .3), int(len(vp) * .7)
    hlo, hhi = int(len(hp) * .3), int(len(hp) * .7)
    centre_vertical = float(np.max(vp[vlo:vhi]) / max(np.median(vp), 1e-6))
    centre_horizontal = float(np.max(hp[hlo:hhi]) / max(np.median(hp), 1e-6))
    hsv = cv2.cvtColor(small, cv2.COLOR_BGR2HSV)
    saturation = hsv[:, :, 1].astype(np.float32) / 255
    hue = hsv[:, :, 0]
    high_sat = saturation > .62
    hist = np.histogram(hue[high_sat], bins=18, range=(0, 180))[0] if np.any(high_sat) else np.zeros(18)
    occupied_hues = int(np.count_nonzero(hist > max(5, int(np.sum(hist) * .015))))
    value = hsv[:, :, 2]
    canvas = (value < 48) | ((value > 247) & (hsv[:, :, 1] < 18))
    border = max(2, min(small.shape[:2]) // 40)
    border_canvas = np.concatenate((canvas[:border].ravel(), canvas[-border:].ravel(), canvas[:, :border].ravel(), canvas[:, -border:].ravel()))
    foreground = np.where(~canvas)
    bbox_ratio = 0.0
    if foreground[0].size:
        bbox_ratio = float(
            (foreground[1].max() - foreground[1].min() + 1)
            * (foreground[0].max() - foreground[0].min() + 1)
            / canvas.size
        )
    gray = cv2.cvtColor(small, cv2.COLOR_BGR2GRAY)
    dhash = cv2.resize(gray, (9, 8), interpolation=cv2.INTER_AREA)
    bits = (dhash[:, 1:] > dhash[:, :-1]).ravel()
    phash = f"{sum(int(bit) << index for index, bit in enumerate(bits)):016x}"
    return {
        "central_vertical_seam_score": round(centre_vertical, 6),
        "central_horizontal_seam_score": round(centre_horizontal, 6),
        "high_saturation_ratio": round(float(np.mean(high_sat)), 6),
        "high_saturation_hue_bins": occupied_hues,
        "canvas_background_ratio": round(float(np.mean(canvas)), 6),
        "canvas_border_ratio": round(float(np.mean(border_canvas)), 6),
        "content_bbox_ratio": round(bbox_ratio, 6),
        "perceptual_hash": phash,
    }


def evaluate_image_path(path: str | Path, preprocessor: ImagePreprocessor | None = None) -> dict[str, Any]:
    """对进入常模的原图做保守门禁；只拒绝明确派生图或不可分析输入。"""
    source = Path(path)
    try:
        payload = source.read_bytes()
    except OSError:
        payload = b""
    source_hash = hashlib.sha256(payload).hexdigest()
    image = cv2.imdecode(np.frombuffer(payload, np.uint8), cv2.IMREAD_COLOR) if payload else None
    if image is None:
        return {
            "gate_version": "input_quality_gate_v0.1.1_integrity", "status": "REJECT",
            "reference_eligible": False, "formal_score_eligible": False,
            "reason_codes": ["decode_failed"], "quality_features": {},
            "source_sha256": source_hash,
        }
    features = _image_derived_features(image)
    reasons: set[str] = set()
    pre = (preprocessor or ImagePreprocessor()).preprocess_image(image)
    flags = {str(flag).lower() for flag in pre.quality_flags}
    if "no_face" in flags:
        reasons.add("no_face")
    if "multiple_faces" in flags or "multi_face" in flags:
        reasons.add("multiple_faces")
    if features["central_vertical_seam_score"] > 4.3 or features["central_horizontal_seam_score"] > 4.3:
        reasons.add("collage")
    if (
        features["canvas_background_ratio"] > .34
        and features["canvas_border_ratio"] > .72
        and features["content_bbox_ratio"] < .84
    ):
        reasons.add("multi_panel")
    if features["high_saturation_ratio"] > .34 and features["high_saturation_hue_bins"] >= 7:
        reasons.add("heatmap")
    status: GateStatus = "REJECT" if reasons & REJECT_CODES else "PASS"
    return {
        "gate_version": "input_quality_gate_v0.1.1_integrity",
        "status": status, "reference_eligible": status == "PASS",
        "formal_score_eligible": status == "PASS", "reason_codes": sorted(reasons),
        "quality_features": {**features, "preprocess_quality_status": pre.quality_status, "preprocess_quality_flags": sorted(pre.quality_flags)},
        "source_sha256": source_hash, "perceptual_hash": features["perceptual_hash"],
    }

